<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { Bot, Cable, CheckCircle2, PlugZap, RefreshCw, Settings2, Sparkles, Unplug, Wrench } from 'lucide-vue-next'
import { apiRequest } from '../lib/api'

interface Integration { id:string;name:string;kind:string;status:string;enabled:boolean;endpoint:string;latency_ms?:number;capabilities:string[] }
interface Skill { id:string;name:string;description:string;source:string;enabled:boolean;version:string }
const integrations=ref<Integration[]>([]),skills=ref<Skill[]>([]),loading=ref(''),notice=ref('')
async function load(){try{const data=await apiRequest<{integrations:Integration[];skills:Skill[]}>('/api/integrations');integrations.value=data.integrations;skills.value=data.skills}catch(error){notice.value=String(error)}}
async function toggleIntegration(item:Integration){loading.value=item.id;try{await apiRequest<Integration>('/api/integrations/'+item.id+'/toggle',{method:'POST'});await load()}finally{loading.value=''}}
async function test(item:Integration){loading.value=item.id;try{const result=await apiRequest<Integration>('/api/integrations/'+item.id+'/test',{method:'POST'});notice.value=result.name+' 连接成功，延迟 '+result.latency_ms+' ms';await load()}catch(error){notice.value=String(error)}finally{loading.value=''}}
async function toggleSkill(skill:Skill){loading.value=skill.id;try{await apiRequest<Skill>('/api/skills/'+skill.id+'/toggle',{method:'POST'});await load()}finally{loading.value=''}}
onMounted(load)
</script>

<template>
  <div class="integration-scroll">
    <section class="integration-hero"><div><span><PlugZap/></span><p><small>EXTENSIBILITY</small><b>Skills 与 MCP</b><em>连接 Codex、社区渠道、监控系统和专用 AI 能力。</em></p></div><i><CheckCircle2/>{{integrations.filter(item=>item.enabled).length}} 个连接已启用</i></section>
    <section class="connection-section"><header><div><small>MCP SERVERS</small><b>外部服务连接</b></div><button><Settings2/>连接配置</button></header><div class="connection-grid"><article v-for="item in integrations" :key="item.id" :class="{disabled:!item.enabled}"><header><span :class="item.status"><Cable v-if="item.enabled"/><Unplug v-else/></span><div><b>{{item.name}}</b><small>{{item.kind.toUpperCase()}} · {{item.status}}</small></div><button :class="{on:item.enabled}" @click="toggleIntegration(item)"><i/></button></header><code>{{item.endpoint}}</code><div class="chips"><i v-for="capability in item.capabilities" :key="capability">{{capability}}</i></div><footer><span><i :class="item.status"></i>{{item.enabled?(item.status==='connected'?'已连接':'已启用'):'已禁用'}}<em v-if="item.latency_ms">{{item.latency_ms}} ms</em></span><button :disabled="!item.enabled||loading===item.id" @click="test(item)"><RefreshCw :class="{spin:loading===item.id}"/>测试连接</button></footer></article></div></section>
    <section class="skill-section"><header><div><small>AGENT SKILLS</small><b>AI 能力包</b></div><span>{{skills.filter(skill=>skill.enabled).length}} / {{skills.length}} 已启用</span></header><div class="skill-grid"><article v-for="skill in skills" :key="skill.id" :class="{disabled:!skill.enabled}"><span><Bot v-if="skill.source==='builtin'"/><Sparkles v-else/></span><p><b>{{skill.name}}</b><small>{{skill.description}}</small><em>{{skill.source}} · v{{skill.version}}</em></p><button :class="{on:skill.enabled}" @click="toggleSkill(skill)"><i/></button></article></div></section>
    <section class="security-note"><Wrench/><div><b>工具权限与审批</b><small>Skills 和 MCP 只能访问显式授权的服务器与目录。停服、玩家处罚、经济修改和正式部署仍需要审批。</small></div></section>
    <div v-if="notice" class="notice">{{notice}}</div>
  </div>
</template>

<style scoped>
