lign-items:center;gap:9px}.connection-grid article>header>span{width:31px;height:31px;display:grid;place-items:center;border-radius:7px;color:#32d5b0;background:rgba(50,213,176,.09)}.connection-grid article>header>span.disabled{color:#727d89;background:#1a2027}.connection-grid article>header>span svg{width:15px}.connection-grid article>header>div{display:flex;flex:1;flex-direction:column}.connection-grid article>header b{font-size:9px}.connection-grid article>header small{margin-top:3px;font-size:7px;text-transform:none}.connection-grid code{display:block;overflow:hidden;margin-top:11px;padding:7px;border-radius:5px;color:#6e7b88;background:#0a0e12;font:7px 'Cascadia Code',monospace;text-overflow:ellipsis;white-space:nowrap}.chips{display:flex;flex-wrap:wrap;gap:4px;margin-top:8px}.chips i{padding:3px 5px;border-radius:4px;color:#8176c8;background:rgba(156,140,255,.07);font:normal 6px Inter}.connection-grid footer{display:flex;align-items:center;justify-content:space-between;margin-top:11px}.connection-grid footer>span{display:flex;align-items:center;gap:5px;color:#64707d;font-size:7px}.connection-grid footer>span>i{width:6px;height:6px;border-radius:50%;background:#68737e}.connection-grid footer>span>i.connected,.connection-grid footer>span>i.ready{background:#32d5b0}.connection-grid footer em{color:#5ebca6;font-style:normal}.connection-grid footer button{height:25px;display:flex;align-items:center;gap:4px;padding:0 7px;border:1px solid rgba(255,255,255,.07);border-radius:5px;color:#7f8b98;background:#171d24;font-size:7px}.connection-grid footer button svg{width:10px}.connection-grid button.on,.skill-grid button.on{background:rgba(50,213,176,.16)}.connection-grid article>header>button,.skill-grid article>button{width:30px;height:17px;padding:2px;border:0;border-radius:10px;background:#2a313a}.connection-grid article>header>button i,.skill-grid article>button i{display:block;width:13px;height:13px;border-radius:50%;background:#7a8591;transition:transform .18s}.connection-grid article>header>button.on i,.skill-grid article>button.on i{background:#32d5b0;transform:translateX(13px)}.skill-section>header>span{color:#6d7986;font-size:7px}.skill-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:7px}.skill-grid article{display:flex;align-items:center;gap:9px;padding:11px;border:1px solid rgba(255,255,255,.065);border-radius:8px;background:#0e1318}.skill-grid article.disabled{opacity:.5}.skill-grid article>span{width:29px;height:29px;display:grid;place-items:center;border-radius:7px;color:#a99dff;background:rgba(156,140,255,.09)}.skill-grid article>span svg{width:14px}.skill-grid p{display:flex;min-width:0;flex:1;flex-direction:column;margin:0}.skill-grid b{font-size:8px}.skill-grid small{overflow:hidden;margin-top:4px;color:#697582;font-size:7px;text-overflow:ellipsis;white-space:nowrap}.skill-grid em{margin-top:4px;color:#53606c;font:normal 6px Inter}.security-note{display:flex;align-items:center;gap:10px;margin-top:10px;padding:13px;color:#e5a86d;background:rgba(243,167,92,.035)}.security-note>svg{width:17px}.security-note div{display:flex;flex-direction:column}.security-note b{font-size:8px}.security-note small{margin-top:4px;color:#716d68;font-size:7px}.notice{position:sticky;bottom:8px;width:max-content;max-width:80%;padding:7px 10px;margin:10px auto 0;border:1px solid rgba(50,213,176,.18);border-radius:7px;color:#86dfca;background:#13211f;font-size:8px}.spin{animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:1000px){.connection-grid,.skill-grid{grid-template-columns:1fr}}
</style>
